package com.example.bandlink.service; import com.example.bandlink.entity.*; import com.example.bandlink.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AdminUserService {private final UserRepository users;private final PostRepository posts;public AdminUserService(UserRepository u,PostRepository p){users=u;posts=p;}@Transactional public void suspend(Long id){User u=change(id,UserStatus.SUSPENDED);posts.findByUserIdAndStatus(id,PostStatus.OPEN).forEach(p->p.close(ClosedReason.SUSPENDED,java.time.LocalDateTime.now()));}@Transactional public void unsuspend(Long id){change(id,UserStatus.ACTIVE);}private User change(Long id,UserStatus s){User u=users.findById(id).orElseThrow();if(u.getStatus()!=UserStatus.WITHDRAWN)u.setStatus(s);return u;}}
